  for(let side of [-1,1])for(let i=0;i<4;i++){const z=-5-i*8,post=new THREE.Group();post.position.set(side*(4.15+(i%2)*.35),0,z);box(post,.16,1.55,.16,'#68452e',0,.77,0);box(post,.52,.12,.16,'#795338',0,1.52,0);box(post,.3,.42,.28,'#ffca63',0,1.24,0);box(post,.36,.08,.34,'#493a32',0,1.47,0);const glow=new THREE.PointLight(0xffb84d,.75,4);glow.position.set(0,1.2,.18);post.add(glow);world3d.add(post);worldProps3d.push(post)}
