function start(){cancelAnimationFrame(raf);paused=false;$('modePicker').style.display='grid';$('resultStats').style.display='none';$('resultHistory').style.display='none';score=combo=peakCombo=hits=misses=elapsed=0;lives=3;left=timeMode==='timed'?60:Infinity;last=0;next=250;nextSkinAt=9+Math.random()*3;nextEnvAt=14+Math.random()*5;rabbit=null;particles=[];texts=[];$('score').textContent='0000';$('hudScore').textContent='0000';$('combo').textContent='×0';$('time').textContent=timeMode==='timed'?'60s':'∞';updateLives();$('overlay').classList.add('hidden');run=true;c.focus({preventScroll:true});beep(550,.09);raf=requestAnimationFrame(frame)}
