function saveRound(){try{let rounds=JSON.parse(localStorage.getItem('bushSlapRounds')||'[]');if(!Array.isArray(rounds))rounds=[];rounds.push({score,combo:peakCombo,hits,misses,when:new Date().toISOString()});rounds.sort((a,b)=>b.score-a.score);localStorage.setItem('bushSlapRounds',JSON.stringify(rounds.slice(0,5)))}catch{}}
function showLeaderboard(){let rounds=[];try{rounds=JSON.parse(localStorage.getItem('bushSlapRounds')||'[]')}catch{}const list=$('leaderboardList');list.replaceChildren();if(!Array.isArray(rounds)||!rounds.length){const li=document.createElement('li');li.textContent='No rounds yet — play your first game!';list.appendChild(li)}else rounds.forEach(r=>{const li=document.createElement('li');li.textContent=String(r.score).padStart(4,'0')+' points · combo ×'+(r.combo||0);list.appendChild(li)});$('leaderboardOverlay').style.display='grid'}
