function rabbitHitTarget(){if(!rabbit)return null;const b=projectRabbit(rabbit.lane,rabbit.depth),touch=('ontouchstart'in window||navigator.maxTouchPoints>0),boost=touch?1.8:1;let cx=b.x,cy,rx,ry;if(renderer3d&&camera3d&&rabbit3d?.visible){camera3d.updateMatrixWorld(true);rabbit3d.updateMatrixWorld(true);const pts=[];for(const xx of [-.48,.48])for(const yy of [.05,2.45])for(const zz of [-.34,.38]){const v=rabbit3d.localToWorld(new THREE.Vector3(xx,yy,zz)).project(camera3d);pts.push({x:(v.x*.5+.5)*W,y:(-v.y*.5+.5)*H})}const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),left=Math.min(...xs),right=Math.max(...xs),top=Math.min(...ys),bottom=Math.max(...ys);cx=(left+right)/2;cy=(top+bottom)/2;rx=Math.max(25,(right-left)*.56)*boost;ry=Math.max(32,(bottom-top)*.52)*boost}else{const scale=Math.max(.65,Math.min(1.6,b.s||1));cy=b.y-12*scale;rx=Math.max(32,38*scale)*boost;ry=Math.max(44,55*scale)*boost}return{x:cx,y:cy,rx,ry,b}}
function hit(e){if(!run)return;let r=c.getBoundingClientRect(),px=(e.clientX-r.left)*W/r.width,py=(e.clientY-r.top)*H/r.height;if(rabbit){const target=rabbitHitTarget(),b=target.b,dx=(px-target.x)/target.rx,dy=(py-target.y)/target.ry;if(dx*dx+dy*dy<=1){hits++;try{if(navigator.vibrate)navigator.vibrate(rabbit.bonus?[24,18,36]:12)}catch{}handSwing=1;arms3d.visible=true;screenShake=reduceMotion?0:7;const ring=document.createElement('div');ring.className='impact-ring';ring.style.left=(b.x/W*100)+'%';ring.style.top=(b.y/H*100)+'%';c.parentElement.appendChild(ring);ring.addEventListener('animationend',()=>ring.remove(),{once:true});const comic=document.createElement('div');comic.className='comic-impact';comic.style.left=(b.x/W*100)+'%';comic.style.top=(b.y/H*100)+'%';c.parentElement.appendChild(comic);comic.addEventListener('animationend',()=>comic.remove(),{once:true});let age=elapsed*1000-(rabbit.born||elapsed*1000),perfect=age<rabbit.maxLife*.3;let streakBonus=Math.min(5,Math.floor(combo/4));let pts=rabbit.points+Math.min(24,combo*2)+streakBonus*5+(perfect?5:0);if(rabbit.bonus){texts.push({x:b.x,y:b.y-130,text:'GOLDEN BUNNY ×3!',color:'#ffe14a',life:1})}if(renderer3d&&rabbit3d){slapThrow3d={t:0,side:rabbit.lane>=0?1:-1};rabbit3d.position.set(rabbit.lane*2.35,.02,-15+rabbit.depth*12);rabbit3d.scale.setScalar(.64)}score+=pts;combo++;peakCombo=Math.max(peakCombo,combo);if(combo>0&&combo%5===0){texts.push({x:W/2,y:H*.28,text:'🔥 '+combo+' HIT STREAK!',color:'#ff7ac0',life:1.15});burst(W/2,H*.34,true);screenShake=reduceMotion?0:Math.max(screenShake,5);beep(820+Math.min(combo,15)*22,.09)}$('score').textContent=fmt(score);$('hudScore').textContent=fmt(score);$('combo').textContent='×'+combo;burst(b.x,b.y-45,perfect);if(perfect){texts.push({x:b.x,y:b.y-150,text:'🔥 PERFECT TIMING!',color:'#67e8f9',life:1});screenShake=reduceMotion?0:10}texts.push({x:b.x,y:b.y-95,text:(perfect?'PERFECT! ':'SLAP! ')+'+'+pts,color:perfect||rabbit.bonus?'#ffe14a':combo>3?'#ff7ac0':'#fff',life:.8});beep((perfect?700:430)+Math.min(combo,10)*38,.06);rabbit=null;next=elapsed*1000+Math.max(170,300-Math.min(110,elapsed*2))+Math.random()*250;return}}handSwing=.45;screenShake=reduceMotion?0:3;misses++;const missedRabbit=!!rabbit,missAge=missedRabbit?elapsed*1000-(rabbit.born||elapsed*1000):0,missText=missedRabbit?(missAge>rabbit.maxLife*.68?'TOO SLOW! −1 ♥':'AIM AGAIN! −1 ♥'):'NO BUNNY! −1 ♥';combo=0;$('combo').textContent='×0';lives=Math.max(0,lives-1);updateLives();texts.push({x:px,y:py-8,text:missText,color:'#ff8aa9',life:.75});beep(120,.08);if(lives===0)finish()}
